import React from 'react';
import './TextBlocks.css'

const KeyValue = ({ caption, text, captionClass = ''}) => {

  return (
    <div>
        <small className={`subdued caption ${captionClass}`}>
            {caption}
        </small>
        <div className="spacer-8"></div>
        <small style={{ whiteSpace: 'pre-line' }}>
            {text}
        </small>
    </div>
  );
};

const IconBullet = ({ img, text }) => {
  return (
    <div className="icon-bullet">
      <span className="icon-bullet-img">{img}</span>
      <span className="icon-bullet-text"><h4>{text}</h4></span>
    </div>
  );
};

const IconBulletSmall = ({ img, text }) => {
  return (
    <div className="icon-bullet-small">
      <span className="icon-bullet-img">{img}</span>
      <span><small>{text}</small></span>
    </div>
  );
};

const Block = ({ caption, title, body, captionClass = '' }) => {
  return (
    <div>
      <p className={`subdued caption ${captionClass}`}>
        {caption}
      </p>
      <div className="spacer-8"></div>
      <h4>{title}</h4>
      {body ? (
        <>
          <div className="spacer-16"></div>
          <p>{body}</p>
        </>
      ) : null}
    </div>
  );
};


const BlockSemiEmphasis = ({ caption, title, body, color = 'inherit'}) => {

  return (
    <div style={{ color }}>
        <p className="subdued caption" style={{ color }}>
          {caption}
        </p>
        <div className="spacer-4"></div>
        <div className="spacer-8"></div>
        <h3>
          {title}
        </h3>
        {body ? (
        <>
          <div className="spacer-24"></div>
          <p style={{ whiteSpace: 'pre-line' }}>{body}</p>
        </>
      ) : null}
    </div>
  );
};

const BlockEmphasis = ({ caption, title, body }) => {

  return (
    <div>
        <p className="subdued caption">
          {caption}
        </p>
        <div className="spacer-16"></div>
        <h2>
          {title}
        </h2>
       {body ? (
        <>
          <div className="spacer-24"></div>
          <p>{body}</p>
        </>
      ) : null}
    </div>
  );
};

const BlockImg = ({ title, img, body }) => {

  return (
     <div>
      <h4>{title}</h4>
      <div className="spacer-16"></div>
      <img src={img} alt="" style={{width:"100%"}}/>
      <div className="spacer-16"></div>
      {Array.isArray(body) ? (
        <ul>
          {body.map((point, index) => (
            <li key={index}>{point}</li>
          ))}
        </ul>
      ) : (
        <p>{body}</p>
      )}
    </div>
  );
};

const ProjectDetails = ({role, collaborators, timeframe, companySize, captionClass = '', styleClass=''}) => {
  
  return (
      <div className="flex-row project-details-condensed-container" style={{gap: '24px'}}>
      <div className = "flex-item">
          <KeyValue
              caption = "My role"
              text = {role}
              captionClass = {captionClass}
          />
      </div>
      <div className = "flex-item">
          <KeyValue
              caption = "Team"
              text = {collaborators}
              captionClass = {captionClass}
          />
      </div>
      <div className = "flex-item">
          <KeyValue
              caption = "Timeframe"
              text = {timeframe}
              captionClass = {captionClass}
          />
      </div>
      { styleClass === 'condensed' ? null :
        <div className = "project-detail-col">
          <KeyValue
              caption = "Company size"
              text = {companySize}
              captionClass = {captionClass}
          />
        </div>
      }
    </div>
  )
}

const ProjectDetailsCondensed = ({role, collaborators, timeframe}) => {
  
  return (
    <div className="flex-row project-details-condensed-container" style={{gap: '24px'}}>
      <div className = "flex-item">
          <KeyValue
              caption = "My role"
              text = {role}
          />
      </div>
      <div className = "flex-item">
          <KeyValue
              caption = "Team"
              text = {collaborators}
          />
      </div>
      <div className = "flex-item">
          <KeyValue
              caption = "Timeframe"
              text = {timeframe}
          />
      </div>
    </div>
  )
}

export { KeyValue, IconBullet, IconBulletSmall, Block, BlockSemiEmphasis, BlockEmphasis, BlockImg, ProjectDetails, ProjectDetailsCondensed };

